import{_ as e,c as d,o as s,ar as a}from"./chunks/framework.BCVse_G_.js";const k=JSON.parse('{"title":"Glass 主题（Frostline）","description":"","frontmatter":{},"headers":[],"relativePath":"theme/glass.md","filePath":"theme/glass.md","lastUpdated":1793100077000}'),o={name:"theme/glass.md"};function i(r,t,n,l,c,h){return s(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="glass-主题-frostline" tabindex="-1">Glass 主题（Frostline） <a class="header-anchor" href="#glass-主题-frostline" aria-label="Permalink to &quot;Glass 主题（Frostline）&quot;">​</a></h1><p><code>nue-ui-theme-glass</code> 是 NueUI 的第二个主题包，视觉语言代号 <strong>Frostline（霜线）</strong>：结霜的光学玻璃 + 阳极氧化金属面板。</p><p>它面向<strong>开发工具 / 技术产品的落地页</strong>——要的是精确可靠，不是潮流。与 <a href="./shadlike.html"><code>nue-ui-theme-shadlike</code></a> 是<strong>并列可选</strong>关系，不是替代。</p><blockquote><p>当前版本：<code>nue-ui-theme-glass@0.2.2</code> 本页右上角的主题开关可以实时切换两个主题，直接对比。</p></blockquote><h2 id="设计语言" tabindex="-1">设计语言 <a class="header-anchor" href="#设计语言" aria-label="Permalink to &quot;设计语言&quot;">​</a></h2><p>整套设计只有两个记忆点：<strong>冷青调</strong> 与 <strong>霜边</strong>，其余一律安静。</p><table tabindex="0"><thead><tr><th>维度</th><th>值</th></tr></thead><tbody><tr><td>色相</td><td><code>192</code>（冷灰青）</td></tr><tr><td>主色饱和</td><td><code>38%</code></td></tr><tr><td>圆角</td><td><code>0.375rem</code>（6px，与 shadlike 相同）</td></tr><tr><td>层次手段</td><td>1px 结构性描边 + 内高光；阴影仅 <code>0 1px 2px</code></td></tr><tr><td>玻璃</td><td><code>blur(16px) saturate(118%)</code>，底色 α0.82 / 0.86</td></tr><tr><td>密度</td><td>紧凑（<code>padding-df 0.875rem</code> · <code>box-size-df 2rem</code>）</td></tr><tr><td>字重</td><td>最高 500，层级靠字号 + 颜色</td></tr></tbody></table><p><strong>霜边</strong>是没有直接用组件库、而是直接看 CSS 就能认出的东西：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">border: 1px solid var(--nue-glass-border); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 外冷线：功能性，对比度 ≥3:1 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">box-shadow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    inset 0 1px 0 hsl(0 0% 100% / 0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.55</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    /* 内白线：霜的结晶线 */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 0 1px 2px hsl(192 40% 10% / 0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.06</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 仅用于脱离背景 */</span></span></code></pre></div><p>分层不靠阴影堆叠，而靠<strong>描边与底色差</strong>——这是它和 shadlike 最本质的区别：shadlike 用柔和投影表达&quot;浮起&quot;，Frostline 用刻线表达&quot;精密&quot;。</p><p>逐 token 的数值差异见 <a href="./design-tokens.html#两个主题的数值差异">设计系统</a>，选择依据见 <a href="./shadlike.html#适合什么场景">Shadlike 主题</a>。</p><h2 id="玻璃分层" tabindex="-1">玻璃分层 <a class="header-anchor" href="#玻璃分层" aria-label="Permalink to &quot;玻璃分层&quot;">​</a></h2><p>不是所有组件都用玻璃。<strong>浮层玻璃化，数据区实底</strong>——这是刻意的分层，不是遗漏。</p><table tabindex="0"><thead><tr><th>层</th><th>组件</th><th>表现</th></tr></thead><tbody><tr><td>玻璃底（9）</td><td><code>overlay</code> <code>dialog</code> <code>drawer</code> <code>dropdown</code> <code>tooltip</code> <code>message</code> <code>confirm</code> <code>prompt</code> <code>popup-pool</code></td><td>半透明底 + 霜边</td></tr><tr><td>其中施加模糊（7）</td><td><code>dialog</code> <code>drawer</code> <code>dropdown</code> <code>tooltip</code> <code>message-node-inner</code> <code>confirm</code> <code>prompt</code></td><td><code>backdrop-filter: var(--nue-glass-blur)</code></td></tr><tr><td>不模糊</td><td><code>overlay</code>（仅全屏遮罩）· <code>popup-pool</code>（0×0 挂载容器）</td><td>全视口模糊是单帧最贵开销</td></tr><tr><td>实底（其余 25 个）</td><td><code>table</code> <code>calendar</code> <code>date-picker</code> <code>input</code> <code>textarea</code> …</td><td>不透明，长阅读不累眼</td></tr></tbody></table><p><code>select</code> / <code>date-picker</code> 的下拉浮层复用 <code>.nue-dropdown</code>，因此自动玻璃化。</p><p><strong>玻璃效果全部由 6 个变量驱动</strong>，组件里不硬编码模糊值：</p><table tabindex="0"><thead><tr><th>变量</th><th>作用</th></tr></thead><tbody><tr><td><code>--nue-glass-bg</code></td><td>半透明玻璃底</td></tr><tr><td><code>--nue-glass-blur</code></td><td><strong>唯一</strong>模糊来源（硬上限 <code>blur ≤ 24px</code>、<code>saturate ≤ 140%</code>）</td></tr><tr><td><code>--nue-glass-border</code></td><td>结构性描边（功能性，参与 3:1 判定）</td></tr><tr><td><code>--nue-glass-solid</code></td><td>退化 / 嵌套实底的唯一落点</td></tr><tr><td><code>--nue-glass-scrim</code></td><td>仅 <code>overlay</code> 全屏遮罩</td></tr><tr><td><code>--nue-glass-shadow</code></td><td>内高光 + 极淡投影</td></tr></tbody></table><h2 id="三条退化路径" tabindex="-1">三条退化路径 <a class="header-anchor" href="#三条退化路径" aria-label="Permalink to &quot;三条退化路径&quot;">​</a></h2><p>玻璃在下列任一条件下会自动退为不透明实底，可读性不受损：</p><ol><li><code>@supports not (backdrop-filter: blur(1px))</code> —— 浏览器不支持模糊</li><li><code>@media (prefers-reduced-transparency: reduce)</code> —— <strong>仅 Chromium 识别</strong></li><li><code>@media (prefers-contrast: more)</code> —— Safari / Firefox 的等价用户意图</li></ol><p>三条路径共用同一组覆写（<code>blur → none</code>、<code>bg → glass-solid</code>、<code>border → border-color</code>），改观感只需改 token，不必逐组件处理。</p><h2 id="字体建议" tabindex="-1">字体建议 <a class="header-anchor" href="#字体建议" aria-label="Permalink to &quot;字体建议&quot;">​</a></h2><p>主题包<strong>不打包 Web Font</strong>，<code>--nue-primary-font-family</code> 仍是系统栈，消费方零字体负担。</p><p>但如果想完整呈现设计意图，推荐自托管 <a href="https://github.com/IBM/plex" target="_blank" rel="noreferrer">IBM Plex Sans</a>（可变 400–500）+ IBM Plex Mono（OFL）：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    --nue-primary-font-family</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;IBM Plex Sans&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-apple-system</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PingFang SC&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sans-serif</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>中文层级不要依赖字重</strong>：中文常见字体只有 400 一档，<code>500</code> 会触发浏览器合成粗体（笔画糊）。层级应该由字号、颜色、间距承担；字重只作拉丁增强，并配合 <code>font-synthesis-weight: none</code> 止损。</p><p>数据、代码、时间戳使用 <code>--nue-font-mono</code> 与 <code>font-variant-numeric: tabular-nums</code>，正文不变量宽字体。</p><h2 id="已知边界" tabindex="-1">已知边界 <a class="header-anchor" href="#已知边界" aria-label="Permalink to &quot;已知边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>边界</th><th>说明</th></tr></thead><tbody><tr><td>阴影与 <code>backdrop-filter</code></td><td>滤镜会把元素渲染成离屏纹理，纹理边界 = border-box，<strong>子元素阴影越界部分被丢弃</strong>。Glass 通过「面板 padding 20px + 阴影收敛到 16px」保证常规状态完整；贴近滚动边缘时仍会被裁一半，属浏览器语义</td></tr><tr><td><code>.nue-content</code> 是滚动容器</td><td>0.2.2 起 <code>content</code> 内部滚动、header 与 aside 固定。若你的外壳按其他方式布局，可能出现双层滚动条，见 <a href="https://github.com/Nathan3303/nue-ui/blob/master/docs/releases/glass-theme-0.2.2.md" target="_blank" rel="noreferrer">发布说明</a></td></tr><tr><td>flex 滚动前提</td><td>自定义布局时，flex 子项默认 <code>min-height: auto</code> 不收缩，<strong>只写 <code>overflow: auto</code> 不会滚动</strong>，必须同时给 <code>min-height: 0</code></td></tr><tr><td>暗色深文本只有两级</td><td>玻璃最坏背景（叠加纯白）压窄了可用对比带，暗色下深文本档收敛为「次级 / 主文本」两档。这是色板的固有代价，不是缺陷——提亮应走字号与霜边，而不是放开饱和度</td></tr><tr><td>与 shadlike 互斥</td><td>两主题变量名一致、作用域相同，<strong>同时引入会互相覆盖</strong></td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>安装与引入 → <a href="./install.html">安装与引入</a></li><li>深色模式 → <a href="./dark-mode.html">深色模式</a></li><li>换主色 / 改玻璃参数 → <a href="./customize.html">定制主题</a></li><li>完整 token 数值差异 → <a href="./design-tokens.html#两个主题的数值差异">设计系统</a></li><li>另一个主题 → <a href="./shadlike.html">Shadlike 主题</a></li></ul>`,31)])])}const g=e(o,[["render",i]]);export{k as __pageData,g as default};
